CREATE DATABASE IF NOT EXISTS bookshop CHARACTER SET utf8mb4; USE bookshop;
CREATE TABLE IF NOT EXISTS books(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,author VARCHAR(255) NOT NULL,category VARCHAR(120),price DECIMAL(10,2) NOT NULL,stock INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO books(title,author,category,price,stock) SELECT 'Clean Code','Robert C. Martin','Programming',650,12 WHERE NOT EXISTS(SELECT 1 FROM books);